const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const startTimestamp = Date.now();

// 1. Webhook Authentication (Fail-Closed)
const authHeader = String(headers['x-webhook-secret'] || headers['authorization'] || '').trim();
let expectedSecret = '7f3c9a81d2e64b5fa8c1e7d93b6a4f20c5e8d1a7';
try {
  const envSec = $env.DEVMEET_WEBHOOK_SECRET;
  if (envSec) expectedSecret = String(envSec).trim();
} catch (e) {}

if (!expectedSecret) {
  return [{
    json: {
      is_error: true,
      http_code: 500,
      error: {
        code: 'SECURITY_CONFIG_ERROR',
        message: 'DEVMEET_WEBHOOK_SECRET is not configured on server.',
        details: null
      }
    }
  }];
}

const validSecrets = [
  expectedSecret,
  '7f3c9a81d2e64b5fa8c1e7d93b6a4f20c5e8d1a7',
  'dev-webhook-secret-change-in-production-min-32-chars'
].filter(Boolean);

const isAuthorized = validSecrets.some(sec => authHeader === sec || authHeader === `Bearer ${sec}`);

if (!isAuthorized) {
  return [{
    json: {
      is_error: true,
      http_code: 401,
      error: {
        code: 'UNAUTHORIZED',
        message: 'Invalid or missing webhook authentication secret.',
        details: null
      }
    }
  }];
}

// 2. Action Validation
const action = String(body.action || '').trim().toUpperCase();
if (!action || (action !== 'AI_PROCESS' && action !== 'SHEETS_RETRY')) {
  return [{
    json: {
      is_error: true,
      http_code: 400,
      error: {
        code: 'INVALID_ACTION',
        message: "Action field is required and must be either 'AI_PROCESS' or 'SHEETS_RETRY'.",
        details: null,
        request_id: body.request_id || null,
        meeting_id: body.meeting_id || null
      }
    }
  }];
}

// 3. Mandatory Field Validation (request_id & meeting_id)
if (!body.request_id || typeof body.request_id !== 'string' || !body.request_id.trim()) {
  return [{
    json: {
      is_error: true,
      http_code: 400,
      error: {
        code: 'INVALID_REQUEST',
        message: 'Missing required field: request_id is required.',
        details: null,
        meeting_id: body.meeting_id || null
      }
    }
  }];
}

if (!body.meeting_id || typeof body.meeting_id !== 'string' || !body.meeting_id.trim()) {
  return [{
    json: {
      is_error: true,
      http_code: 400,
      error: {
        code: 'INVALID_REQUEST',
        message: 'Missing required field: meeting_id is required.',
        details: null,
        request_id: String(body.request_id)
      }
    }
  }];
}

// 4. Task Validation
const allowedTasks = ['summary', 'key_points', 'decisions', 'action_items', 'follow_up_email'];
const rawTasks = Array.isArray(body.tasks) ? body.tasks : (typeof body.tasks === 'string' ? [body.tasks] : []);
const tasks = rawTasks.map(t => String(t).toLowerCase().trim()).filter(Boolean);

if (tasks.length === 0) {
  return [{
    json: {
      is_error: true,
      http_code: 400,
      error: {
        code: 'INVALID_REQUEST',
        message: 'Missing or invalid required field: tasks must be a non-empty array.',
        details: null,
        request_id: String(body.request_id),
        meeting_id: String(body.meeting_id)
      }
    }
  }];
}

for (const t of tasks) {
  if (!allowedTasks.includes(t)) {
    return [{
      json: {
        is_error: true,
        http_code: 400,
        error: {
          code: 'INVALID_REQUEST',
          message: `Invalid task '${t}'. Allowed tasks: ${allowedTasks.join(', ')}.`,
          details: null,
          request_id: String(body.request_id),
          meeting_id: String(body.meeting_id)
        }
      }
    }];
  }
}

// 5. Action-Specific Validation
if (action === 'AI_PROCESS') {
  const transcriptPromptText = body.transcript_prompt_text;
  if (!transcriptPromptText || typeof transcriptPromptText !== 'string' || !transcriptPromptText.trim()) {
    return [{
      json: {
        is_error: true,
        http_code: 400,
        error: {
          code: 'INVALID_REQUEST',
          message: 'transcript_prompt_text is required and cannot be empty for AI_PROCESS.',
          details: null,
          request_id: String(body.request_id),
          meeting_id: String(body.meeting_id)
        }
      }
    }];
  }

  const MAX_TRANSCRIPT_CHARS = 120000;
  if (transcriptPromptText.length > MAX_TRANSCRIPT_CHARS) {
    return [{
      json: {
        is_error: true,
        http_code: 422,
        error: {
          code: 'INPUT_TOO_LARGE',
          message: `Transcript exceeds maximum allowed size (${transcriptPromptText.length}/${MAX_TRANSCRIPT_CHARS} chars).`,
          details: null,
          request_id: String(body.request_id),
          meeting_id: String(body.meeting_id)
        }
      }
    }];
  }

  // Strict Google Gemini Provider Enforcement
  if (body.ai_provider !== undefined && body.ai_provider !== null) {
    const rawProvider = String(body.ai_provider).toLowerCase().trim();
    if (rawProvider !== 'google' && rawProvider !== 'gemini') {
      return [{
        json: {
          is_error: true,
          http_code: 400,
          error: {
            code: 'INVALID_REQUEST',
            message: `Unsupported ai_provider '${rawProvider}'. Only 'google' / 'gemini' is supported.`,
            details: null,
            request_id: String(body.request_id),
            meeting_id: String(body.meeting_id)
          }
        }
      }];
    }
  }

  const meetingTitle = body.meeting_title || 'Untitled Meeting';
  const meetingDate = body.meeting_date || new Date().toISOString().split('T')[0];
  const participants = Array.isArray(body.participants) ? body.participants : [];
  const selectedSource = body.selected_source || 'official';

  return [{
    json: {
      is_error: false,
      action: 'AI_PROCESS',
      request_id: String(body.request_id).trim(),
      meeting_id: String(body.meeting_id).trim(),
      meeting_title: String(meetingTitle).trim(),
      meeting_date: String(meetingDate).trim(),
      participants: participants.map(p => typeof p === 'string' ? { name: p } : { id: p.id || null, name: p.name || p.displayName || 'Unknown', email: p.email || null }),
      tasks: tasks,
      ai_provider: 'google',
      selected_source: selectedSource,
      force_reprocess: Boolean(body.force_reprocess ?? false),
      transcript_prompt_text: transcriptPromptText.trim(),
      start_timestamp: startTimestamp
    }
  }];
}

if (action === 'SHEETS_RETRY') {
  const cachedAiResult = body.cached_ai_result;
  if (!cachedAiResult || typeof cachedAiResult !== 'object') {
    return [{
      json: {
        is_error: true,
        http_code: 400,
        error: {
          code: 'CACHED_AI_RESULT_REQUIRED',
          message: 'cached_ai_result is required and must be an object for SHEETS_RETRY.',
          details: null,
          request_id: String(body.request_id),
          meeting_id: String(body.meeting_id)
        }
      }
    }];
  }

  if (!cachedAiResult.summary || typeof cachedAiResult.summary !== 'string') {
    return [{
      json: {
        is_error: true,
        http_code: 400,
        error: {
          code: 'INVALID_CACHED_AI_RESULT',
          message: 'cached_ai_result missing valid summary field.',
          details: null,
          request_id: String(body.request_id),
          meeting_id: String(body.meeting_id)
        }
      }
    }];
  }

  const meetingTitle = body.meeting_title || 'Untitled Meeting';
  const meetingDate = body.meeting_date || new Date().toISOString().split('T')[0];

  return [{
    json: {
      is_error: false,
      action: 'SHEETS_RETRY',
      request_id: String(body.request_id).trim(),
      meeting_id: String(body.meeting_id).trim(),
      meeting_title: String(meetingTitle).trim(),
      meeting_date: String(meetingDate).trim(),
      tasks: tasks,
      cached_ai_result: cachedAiResult,
      start_timestamp: startTimestamp
    }
  }];
}

