const inputData = $('Authenticate & Validate Input').item.json;
const rawOutput = $json.output ?? $json.response?.output ?? $json.result ?? $json;

function validateAiResponse(raw) {
  if (!raw) return { valid: false, error: 'Empty output from AI model.' };

  let parsed = raw;
  if (typeof raw === 'string') {
    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      return { valid: false, error: `Invalid JSON format: ${e.message}` };
    }
  }

  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return { valid: false, error: 'AI output root must be a JSON object.' };
  }

  if (!parsed.summary || typeof parsed.summary !== 'string' || !parsed.summary.trim()) {
    return { valid: false, error: 'Missing or empty required field: summary.' };
  }

  if (!Array.isArray(parsed.key_points)) {
    return { valid: false, error: 'Field key_points must be an array of strings.' };
  }
  for (let i = 0; i < parsed.key_points.length; i++) {
    const kp = parsed.key_points[i];
    if (typeof kp !== 'string' || !kp.trim()) {
      return { valid: false, error: `key_points element at index ${i} must be a non-empty string.` };
    }
  }

  if (!Array.isArray(parsed.decisions)) {
    return { valid: false, error: 'Field decisions must be an array.' };
  }
  for (let i = 0; i < parsed.decisions.length; i++) {
    const d = parsed.decisions[i];
    if (!d || typeof d !== 'object' || Array.isArray(d)) {
      return { valid: false, error: `decisions element at index ${i} must be an object.` };
    }
    if (!d.decision || typeof d.decision !== 'string' || !d.decision.trim()) {
      return { valid: false, error: `Decision at index ${i} missing required non-empty string 'decision'.` };
    }
    if (d.context === undefined || d.context === null || typeof d.context !== 'string') {
      return { valid: false, error: `Decision at index ${i} missing required string 'context'.` };
    }
    if (!d.evidence_timestamp || typeof d.evidence_timestamp !== 'string' || !d.evidence_timestamp.trim()) {
      return { valid: false, error: `Decision at index ${i} missing required non-empty string 'evidence_timestamp'.` };
    }
  }

  const ALLOWED_STATUSES = ['TODO'];
  if (!Array.isArray(parsed.action_items)) {
    return { valid: false, error: 'Field action_items must be an array.' };
  }
  for (let i = 0; i < parsed.action_items.length; i++) {
    const a = parsed.action_items[i];
    if (!a || typeof a !== 'object' || Array.isArray(a)) {
      return { valid: false, error: `action_items element at index ${i} must be an object.` };
    }
    if (!a.task || typeof a.task !== 'string' || !a.task.trim()) {
      return { valid: false, error: `Action item at index ${i} missing required non-empty string 'task'.` };
    }
    if (a.status === undefined || a.status === null || typeof a.status !== 'string' || !ALLOWED_STATUSES.includes(a.status)) {
      return { valid: false, error: `Action item at index ${i} has invalid status '${a ? a.status : null}'. Allowed status enum: ${ALLOWED_STATUSES.join(', ')}.` };
    }
    if (!a.evidence_timestamp || typeof a.evidence_timestamp !== 'string' || !a.evidence_timestamp.trim()) {
      return { valid: false, error: `Action item at index ${i} missing required non-empty string 'evidence_timestamp'.` };
    }
  }

  const email = parsed.follow_up_email;
  if (!email || typeof email !== 'object' || Array.isArray(email)) {
    return { valid: false, error: 'Field follow_up_email must be an object.' };
  }
  if (!email.subject || typeof email.subject !== 'string' || !email.subject.trim()) {
    return { valid: false, error: 'follow_up_email.subject must be a non-empty string.' };
  }
  if (!email.body || typeof email.body !== 'string' || !email.body.trim()) {
    return { valid: false, error: 'follow_up_email.body must be a non-empty string.' };
  }

  return { valid: true, data: parsed };
}

const valResult = validateAiResponse(rawOutput);

if (!valResult.valid || $json.error) {
  return [{
    json: {
      is_error: true,
      retry_needed: true,
      validation_error_message: valResult.error || String($json.error?.message || $json.error),
      request_id: inputData.request_id,
      meeting_id: inputData.meeting_id,
      meeting_title: inputData.meeting_title,
      meeting_date: inputData.meeting_date,
      tasks: inputData.tasks,
      participants: inputData.participants,
      transcript_prompt_text: inputData.transcript_prompt_text,
      start_timestamp: inputData.start_timestamp
    }
  }];
}

const aiOutput = valResult.data;

const meetingRow = {
  meeting_id: inputData.meeting_id,
  date: inputData.meeting_date,
  title: inputData.meeting_title,
  summary: aiOutput.summary.trim(),
  created_at: new Date().toISOString(),
  idempotency_key: `meeting:${inputData.meeting_id}:request:${inputData.request_id}:meeting`
};

const decisionRows = aiOutput.decisions.map((d, idx) => ({
  meeting_id: inputData.meeting_id,
  decision: String(d.decision).trim(),
  context: String(d.context || '').trim(),
  evidence_timestamp: String(d.evidence_timestamp).trim(),
  idempotency_key: `meeting:${inputData.meeting_id}:request:${inputData.request_id}:decision:${idx}`
