      follow_up_email: { subject: emailRow.subject, body: emailRow.body }
    },
    sheets_payload: {
      meeting_row: meetingRow,
      decision_rows: decisionRows,
      action_item_rows: actionItemRows,
      email_row: emailRow
    }
  }
}];

