const inputData = $json;
const cached = inputData.cached_ai_result || {};

const meetingRow = {
  meeting_id: inputData.meeting_id,
  date: inputData.meeting_date,
  title: inputData.meeting_title,
  summary: String(cached.summary || '').trim(),
  created_at: new Date().toISOString(),
  idempotency_key: `meeting:${inputData.meeting_id}:request:${inputData.request_id}:meeting`
};

const decisionRows = Array.isArray(cached.decisions)
  ? cached.decisions.map((d, idx) => ({
      meeting_id: inputData.meeting_id,
      decision: String(d.decision || '').trim(),
      context: String(d.context || '').trim(),
      evidence_timestamp: String(d.evidence_timestamp || '').trim(),
      idempotency_key: `meeting:${inputData.meeting_id}:request:${inputData.request_id}:decision:${idx}`
    }))
  : [];

const actionItemRows = Array.isArray(cached.action_items)
  ? cached.action_items.map((a, idx) => ({
      meeting_id: inputData.meeting_id,
      task: String(a.task || '').trim(),
      assignee: a.assignee ? String(a.assignee).trim() : 'Unassigned',
      deadline: a.deadline ? String(a.deadline).trim() : 'None',
      status: 'TODO',
      evidence_timestamp: String(a.evidence_timestamp || '').trim(),
      idempotency_key: `meeting:${inputData.meeting_id}:request:${inputData.request_id}:action:${idx}`
    }))
  : [];

const emailObj = cached.follow_up_email || {};
const emailRow = {
  meeting_id: inputData.meeting_id,
  subject: String(emailObj.subject || '').trim(),
  body: String(emailObj.body || '').trim(),
  idempotency_key: `meeting:${inputData.meeting_id}:request:${inputData.request_id}:email`
};

return [{
  json: {
    is_error: false,
    retry_needed: false,
    action: 'SHEETS_RETRY',
    request_id: inputData.request_id,
    meeting_id: inputData.meeting_id,
    meeting_title: inputData.meeting_title,
    meeting_date: inputData.meeting_date,
    start_timestamp: inputData.start_timestamp,
    ai_output: cached,
    sheets_payload: {
      meeting_row: meetingRow,
      decision_rows: decisionRows,
      action_item_rows: actionItemRows,
      email_row: emailRow
    }
  }
}];

